  "4-2-bond-cycle": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 470 270\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Energy level diagram for hydrogen plus chlorine forming hydrogen chloride. An upward arrow labelled bonds broken, plus 678 kilojoules per mole, rises from the reactants H2 plus Cl2 to separate gaseous atoms 2H plus 2Cl. A longer downward arrow labelled bonds formed, minus 862 kilojoules per mole, falls to the products 2HCl, below the reactants. A short downward arrow from the reactants level to the products level is labelled delta H equals minus 184 kilojoules per mole.</title>\n  <path d=\"M24.0 262.0 L24.0 33.0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n  <polygon points=\"24.0,24.0 19.5,33.0 28.5,33.0\" fill=\"currentColor\"/>\n  <text x=\"16\" y=\"150\" font-size=\"12\" fill=\"currentColor\" font-family=\"inherit\" text-anchor=\"middle\" transform=\"rotate(-90 16 150)\">enthalpy</text>\n  <g stroke=\"currentColor\" stroke-width=\"2.2\">\n    <path d=\"M50 170 H190\"/>\n    <path d=\"M130 40 H350\"/>\n    <path d=\"M280 205 H455\"/>\n  </g>\n  <path d=\"M190 170 H455\" stroke=\"var(--muted)\" stroke-width=\"1.2\" stroke-dasharray=\"4 4\" fill=\"none\"/>\n  <g font-size=\"13\" fill=\"currentColor\" font-family=\"inherit\" text-anchor=\"middle\">\n    <text x=\"120\" y=\"190\">H<tspan baseline-shift=\"sub\" font-size=\"10\">2</tspan>(g) + Cl<tspan baseline-shift=\"sub\" font-size=\"10\">2</tspan>(g)</text>\n    <text x=\"240\" y=\"30\">2H(g) + 2Cl(g)</text>\n    <text x=\"368\" y=\"225\">2HCl(g)</text>\n  </g>\n  <path d=\"M150.0 168.0 L150.0 52.0\" fill=\"none\" stroke=\"var(--t1-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"150.0,43.0 145.5,52.0 154.5,52.0\" fill=\"var(--t1-ink)\"/>\n  <path d=\"M300.0 42.0 L300.0 193.0\" fill=\"none\" stroke=\"var(--t2-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"300.0,202.0 304.5,193.0 295.5,193.0\" fill=\"var(--t2-ink)\"/>\n  <path d=\"M445.0 171.0 L445.0 196.0\" fill=\"none\" stroke=\"var(--t3-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"445.0,203.0 448.5,196.0 441.5,196.0\" fill=\"var(--t3-ink)\"/>\n  <g font-size=\"12\" font-family=\"inherit\">\n    <text x=\"142\" y=\"100\" text-anchor=\"end\" fill=\"var(--t1-ink)\">bonds broken</text>\n    <text x=\"142\" y=\"116\" text-anchor=\"end\" fill=\"var(--t1-ink)\">+678 kJ mol⁻¹</text>\n    <text x=\"308\" y=\"110\" fill=\"var(--t2-ink)\">bonds formed</text>\n    <text x=\"308\" y=\"126\" fill=\"var(--t2-ink)\">−862 kJ mol⁻¹</text>\n    <text x=\"455\" y=\"160\" text-anchor=\"end\" fill=\"var(--t3-ink)\">ΔH = −184 kJ mol⁻¹</text>\n  </g>\n</svg>",
  "4-2-hess-cycle": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 460 255\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Triangular energy cycle. Top left: C(s) plus O2(g). Top right: CO(g) plus one half O2(g). Bottom centre: CO2(g). An arrow from top left to top right is labelled delta H, unknown. An arrow from top left down to CO2 is labelled minus 394 kilojoules per mole. An arrow from top right down to CO2 is labelled minus 283 kilojoules per mole. Below: delta H plus minus 283 equals minus 394.</title>\n  <g font-size=\"14\" fill=\"currentColor\" font-family=\"inherit\" text-anchor=\"middle\">\n    <text x=\"90\" y=\"52\">C(s) + O<tspan baseline-shift=\"sub\" font-size=\"10\">2</tspan>(g)</text>\n    <text x=\"365\" y=\"52\">CO(g) + ½O<tspan baseline-shift=\"sub\" font-size=\"10\">2</tspan>(g)</text>\n    <text x=\"228\" y=\"206\">CO<tspan baseline-shift=\"sub\" font-size=\"10\">2</tspan>(g)</text>\n  </g>\n  <path d=\"M160.0 47.0 L276.0 47.0\" fill=\"none\" stroke=\"var(--t3-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"285.0,47.0 276.0,42.5 276.0,51.5\" fill=\"var(--t3-ink)\"/>\n  <path d=\"M95.0 64.0 L199.0 179.3\" fill=\"none\" stroke=\"var(--t1-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"205.0,186.0 202.3,176.3 195.6,182.3\" fill=\"var(--t1-ink)\"/>\n  <path d=\"M360.0 64.0 L258.0 179.3\" fill=\"none\" stroke=\"var(--t2-ink)\" stroke-width=\"1.8\"/>\n  <polygon points=\"252.0,186.0 261.3,182.2 254.6,176.3\" fill=\"var(--t2-ink)\"/>\n  <g font-size=\"12\" font-family=\"inherit\">\n    <text x=\"222\" y=\"36\" text-anchor=\"middle\" fill=\"var(--t3-ink)\">ΔH = ?</text>\n    <text x=\"140\" y=\"140\" text-anchor=\"end\" fill=\"var(--t1-ink)\">−394 kJ mol⁻¹</text>\n    <text x=\"316\" y=\"140\" fill=\"var(--t2-ink)\">−283 kJ mol⁻¹</text>\n  </g>\n  <text x=\"228\" y=\"240\" font-size=\"13\" fill=\"currentColor\" font-family=\"inherit\" text-anchor=\"middle\">ΔH + (−283) = −394</text>\n</svg>",
